package org.kendar.dlna.transcoding;

import java.io.IOException;
import java.io.RandomAccessFile;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.file.Path;
import java.util.Arrays;

/**
 * Virtual tracks cut from the original file without re-encoding. A slice is a few generated bytes followed by a byte
 * range of the file.
 *
 * <ul>
 *   <li>WAV (PCM): a new header and the exact bytes of the sample range, so the cut is sample accurate.</li>
 *   <li>MP3: the whole frames that cover the sample range (a granularity of one frame, 1152 samples), as is.</li>
 * </ul>
 */
public final class Slices {

    private Slices() {
    }

    /**
     * The bytes {@code head} followed by {@code length} bytes of the file from {@code offset}.
     */
    public record Slice(byte[] head, long offset, long length) {
        public long total() {
            return head.length + length;
        }
    }

    /** Sample accurate cut of a PCM WAV file. */
    public static Slice wav(Path file, long startSample, long endSample) throws IOException {
        try (RandomAccessFile f = new RandomAccessFile(file.toFile(), "r")) {
            byte[] riff = new byte[12];
            f.readFully(riff);
            if (!new String(riff, 0, 4, java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF")
                    || !new String(riff, 8, 4, java.nio.charset.StandardCharsets.US_ASCII).equals("WAVE")) {
                throw new IOException("not a WAV file: " + file.getFileName());
            }
            byte[] fmt = null;
            long dataOffset = -1;
            long dataSize = 0;
            long len = f.length();
            while (f.getFilePointer() + 8 <= len) {
                byte[] h = new byte[8];
                f.readFully(h);
                String id = new String(h, 0, 4, java.nio.charset.StandardCharsets.US_ASCII);
                long size = ByteBuffer.wrap(h, 4, 4).order(ByteOrder.LITTLE_ENDIAN).getInt() & 0xFFFFFFFFL;
                long body = f.getFilePointer();
                if (id.equals("fmt ")) {
                    fmt = new byte[(int) size];
                    f.readFully(fmt);
                } else if (id.equals("data")) {
                    dataOffset = body;
                    dataSize = Math.min(size, len - body);
                    break;
                }
                f.seek(body + size + (size & 1));
            }
            if (fmt == null || dataOffset < 0 || fmt.length < 16) {
                throw new IOException("WAV file without fmt or data chunk: " + file.getFileName());
            }
            int tag = ByteBuffer.wrap(fmt).order(ByteOrder.LITTLE_ENDIAN).getShort(0) & 0xFFFF;
            int blockAlign = ByteBuffer.wrap(fmt).order(ByteOrder.LITTLE_ENDIAN).getShort(12) & 0xFFFF;
            if ((tag != 1 && tag != 0xFFFE) || blockAlign <= 0) {
                throw new IOException("only PCM WAV can be cut: " + file.getFileName());
            }
            long frames = dataSize / blockAlign;
            long from = Math.max(0, Math.min(startSample, frames));
            long to = Math.max(from, Math.min(endSample, frames));
            long bytes = (to - from) * blockAlign;
            int fmtLen = fmt.length + (fmt.length & 1);
            ByteBuffer head = ByteBuffer.allocate(12 + 8 + fmtLen + 8).order(ByteOrder.LITTLE_ENDIAN);
            head.put(new byte[] {'R', 'I', 'F', 'F'});
            head.putInt((int) Math.min(0xFFFFFFFFL, 4 + 8 + fmtLen + 8 + bytes));
            head.put(new byte[] {'W', 'A', 'V', 'E', 'f', 'm', 't', ' '});
            head.putInt(fmt.length);
            head.put(fmt);
            if ((fmt.length & 1) != 0) {
                head.put((byte) 0);
            }
            head.put(new byte[] {'d', 'a', 't', 'a'});
            head.putInt((int) Math.min(0xFFFFFFFFL, bytes));
            return new Slice(head.array(), dataOffset + from * blockAlign, bytes);
        }
    }

    /** Frame granular cut of an MP3 file: the frames overlapping [startSample, endSample). */
    public static Slice mp3(Path file, long startSample, long endSample) throws IOException {
        Frames fr = frames(file);
        long first = Math.max(0, Math.min(startSample / fr.samplesPerFrame, fr.count()));
        long last = Math.max(first, Math.min((endSample + fr.samplesPerFrame - 1) / fr.samplesPerFrame, fr.count()));
        long from = fr.offsets[(int) first];
        long to = fr.offsets[(int) last];
        return new Slice(new byte[0], from, to - from);
    }

    private record Frames(long[] offsets, int samplesPerFrame) {
        /** Number of audio frames; {@code offsets} holds one more entry: the end of the last frame. */
        int count() {
            return offsets.length - 1;
        }
    }

    private static final int[][] BITRATES = {
        {0, 32, 64, 96, 128, 160, 192, 224, 256, 288, 320, 352, 384, 416, 448},   // MPEG1 layer I (unused)
        {0, 32, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 384},      // MPEG1 layer II (unused)
        {0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320},       // MPEG1 layer III
        {0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160}            // MPEG2 / 2.5 layer III
    };
    private static final int[] RATES_V1 = {44100, 48000, 32000};

    private static Frames frames(Path file) throws IOException {
        byte[] data = java.nio.file.Files.readAllBytes(file);
        int pos = 0;
        if (data.length >= 10 && data[0] == 'I' && data[1] == 'D' && data[2] == '3') {
            pos = 10 + ((data[6] & 0x7f) << 21 | (data[7] & 0x7f) << 14 | (data[8] & 0x7f) << 7 | (data[9] & 0x7f));
        }
        long[] offsets = new long[1024];
        int n = 0;
        int spf = 1152;
        long end = 0;
        boolean first = true;
        while (pos + 4 <= data.length) {
            int b1 = data[pos + 1] & 0xff;
            if ((data[pos] & 0xff) != 0xFF || (b1 & 0xE0) != 0xE0) {
                pos++;
                continue;
            }
            int version = (b1 >> 3) & 3;   // 3 = MPEG1, 2 = MPEG2, 0 = 2.5
            int layer = (b1 >> 1) & 3;     // 1 = layer III
            int b2 = data[pos + 2] & 0xff;
            int bri = b2 >> 4;
            int sri = (b2 >> 2) & 3;
            if (version == 1 || layer != 1 || bri == 0 || bri == 15 || sri == 3) {
                pos++;
                continue;
            }
            boolean v1 = version == 3;
            int rate = v1 ? RATES_V1[sri] : RATES_V1[sri] / (version == 2 ? 2 : 4);
            int kbps = BITRATES[v1 ? 2 : 3][bri];
            int pad = (b2 >> 1) & 1;
            int len = (v1 ? 144 : 72) * kbps * 1000 / rate + pad;
            spf = v1 ? 1152 : 576;
            if (len < 4 || pos + len > data.length) {
                break;
            }
            boolean info = first && isInfoFrame(data, pos, v1, (data[pos + 3] >> 6 & 3) == 3);
            first = false;
            if (!info) {
                if (n + 2 > offsets.length) {
                    offsets = Arrays.copyOf(offsets, offsets.length * 2);
                }
                offsets[n++] = pos;
            }
            pos += len;
            end = pos;
        }
        if (n == 0) {
            throw new IOException("no MP3 frames in " + file.getFileName());
        }
        offsets[n] = end;
        return new Frames(Arrays.copyOf(offsets, n + 1), spf);
    }

    /** The Xing / Info frame a VBR or LAME encoder puts first carries no audio. */
    private static boolean isInfoFrame(byte[] d, int pos, boolean v1, boolean mono) {
        int at = pos + 4 + (v1 ? (mono ? 17 : 32) : (mono ? 9 : 17));
        if (at + 4 > d.length) {
            return false;
        }
        String tag = new String(d, at, 4, java.nio.charset.StandardCharsets.US_ASCII);
        return tag.equals("Xing") || tag.equals("Info");
    }
}
